   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是。离伊凡城破冰船维护工作结束的时间只剩下最后一天了，但我调查发现，涅普露这个女人似乎不在船坞里。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="现在明明是最关键的时期，但她却不在船坞，一定事出有因，而且——", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我跟您说过，她总会去找的那个吟游诗人，也从城区彻底消失了。两人几乎是同时不见的。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="副官整理了一下思路，沉声告诉芙兰朵。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伊凡城从上到下都知道破冰船的能源燃料缺口极大，城内储备根本不够启动破冰作业。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可老将军明明知道这一点，却依旧强令我们优先保障船坞的维修资源，甚至为此挪用了部分城防物资。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="结合涅普露和弦枝的突然失踪，属下大胆推断：老将军一定是和涅普露达成了某种合作——他们要去某个地方寻找破冰船的燃料，而那个地方，只有涅普露知道如何进入。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是嘛……", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那你觉得……她们会去哪里了呢？", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="属下已有判断，芙兰朵大人。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="属下虽然是被迫来到这边境城市，但也待了许多年，清楚这里的底细。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有概率藏着能源燃料、还需要特殊手段才能进入的地方只有一个。传说中，黄金航线的起点——伊凡城之下，现在被称为“禁区”的灯塔！", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管只是传说，但那里据说封存着黄金时代的遗留物资，也是老将军一直严令封锁、不许任何人靠近的区域。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那你知不知道，为什么将军不愿意亲自带队去找呢？", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这……属下不知，可能是因为伊凡城的军事力量太过薄弱，没办法对付禁区里的异变体吧。", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……有点意思，你倒是比我想象中的聪明呢。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="全靠大人提点！属下不甘一直困在这地方，只想为帝国和大统领效力，渴望能得到重用，而不是在这里虚度光阴……", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="呵呵呵，想要重用倒是不难……", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="副官狂喜，他更加确认自己的选择没有错。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从芙兰朵在前一天联系到他时，他立即意识到自己翻身的机会终于要来了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如今大统领宣布将帝国事务交给芙兰朵代管后，他和所有人都意识到这个女人的地位已经不是刚来那会的“花瓶”了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大人的意思是……", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你录下的那些证据，足够把老将军从他的位置上拉下来——这个伊凡城卫队将军的位置，我让你来坐，如何？", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……啊？！", msg_color="", msg_size=0, talker="卫队副官", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……你很不满吗？", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_110.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
